// Oeste Stat — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/stat

export function Stat({ label, value, unit }) {
  return (
    <div className="flex flex-col gap-1">
      <span className="text-[17px] font-medium leading-[1] text-[var(--color-body)]">{label}</span>
      <span className="flex items-end gap-1">
        <span className="text-[28px] font-bold leading-[1] tracking-[-0.025em] text-[var(--color-ink)]">{value}</span>
        {unit && <span className="text-[13px] leading-[1] text-[var(--color-muted)]">{unit}</span>}
      </span>
    </div>
  );
}
